import assert from "node:assert/strict";
import { test } from "node:test";
import { createTask, updateTask, getTask, listTasks, serializeTask } from "../src/store.js";

function fixture(id, updated_at = "2026-03-01T10:00:00Z") {
	return { id, title: "original", status: "open", updated_at };
}

test("serialization reuses entries keyed by id and updated_at", () => {
	const task = fixture("cache-key");
	const first = serializeTask(task);
	assert.strictEqual(serializeTask({ ...task }), first);
	const revised = { ...task, title: "revised", updated_at: "2026-03-01T10:00:01Z" };
	const second = serializeTask(revised);
	assert.notStrictEqual(second, first);
	assert.equal(second.title, "revised");
	assert.notStrictEqual(serializeTask(fixture("another-id")), first);
});

test("PATCH invalidates cached tasks even within the same second", () => {
	const now = new Date("2026-03-01T10:00:00.100Z");
	const task = createTask("original", now);
	assert.strictEqual(getTask(task.id), task);
	const updated = updateTask(task.id, { status: "done" }, new Date("2026-03-01T10:00:00.900Z"));
	assert.equal(updated.updated_at, task.updated_at);
	assert.notStrictEqual(updated, task);
	assert.equal(updated.status, "done");
	assert.strictEqual(getTask(task.id), updated);
	assert.strictEqual(listTasks().find(item => item.id === task.id), updated);
	const later = updateTask(task.id, { title: "later" }, new Date("2026-03-01T10:00:01Z"));
	assert.equal(getTask(task.id).title, "later");
	assert.notStrictEqual(later, updated);
});

test("cached serialized tasks cannot be mutated by callers", () => {
	const task = createTask("immutable result");
	assert.ok(Object.isFrozen(task));
	assert.throws(() => { task.title = "corrupted"; }, TypeError);
	assert.equal(getTask(task.id).title, "immutable result");
});

test("LRU holds at most 500 entries and refreshes entries on access", () => {
	const entries = Array.from({ length: 500 }, (_, i) => fixture(`lru-${i}`));
	const serialized = entries.map(serializeTask);
	assert.strictEqual(serializeTask(entries[0]), serialized[0]);
	serializeTask(fixture("lru-overflow"));
	assert.strictEqual(serializeTask(entries[0]), serialized[0]);
	assert.notStrictEqual(serializeTask(entries[1]), serialized[1]);
});

