import { createTask, getTask, listTasks, updateTask } from "../store.js";

function error(status, code, message) {
	return { status, body: { error: { code, message } } };
}

function taskResponse(task) {
	return task
		? { status: 200, body: task }
		: error(404, "not_found", "not found");
}

function listResponse(url) {
	const limit = Number(url.searchParams.get("limit") ?? 25);
	if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
		return error(400, "invalid_limit", "limit must be an integer between 1 and 100");
	}
	return { status: 200, body: { items: listTasks().slice(0, limit) } };
}

function writeResponse(method, id, body) {
	let data;
	try {
		data = JSON.parse(body || "{}");
	} catch {
		return error(400, "invalid_json", "request body must be valid JSON");
	}
	if (!data || typeof data !== "object" || Array.isArray(data)) {
		return error(400, "invalid_body", "request body must be a JSON object");
	}
	if (method === "PATCH") return taskResponse(updateTask(id, data));
	if (typeof data.title !== "string" || !data.title.trim()) {
		return error(400, "invalid_title", "title must be a non-empty string");
	}
	return { status: 201, body: createTask(data.title) };
}

export function handle(method, url, body) {
	const parts = url.pathname.split("/").filter(Boolean);
	if (parts[0] !== "tasks" || parts.length > 2) {
		return error(404, "not_found", "not found");
	}
	if (method === "GET" && parts.length === 1) return listResponse(url);
	if (method === "POST" && parts.length === 1) return writeResponse(method, undefined, body);
	if (method === "GET") return taskResponse(getTask(parts[1]));
	if (method === "PATCH" && parts.length === 2) return writeResponse(method, parts[1], body);
	return error(405, "method_not_allowed", "method not allowed");
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { handle } from "../src/routes/tasks.js";

function request(method, path, body) {
	return handle(method, new URL(path, "http://localhost"), body);
}

function expectError(response, status, code) {
	assert.equal(response.status, status);
	assert.deepEqual(Object.keys(response.body), ["error"]);
	assert.deepEqual(Object.keys(response.body.error).sort(), ["code", "message"]);
	assert.equal(response.body.error.code, code);
	assert.equal(typeof response.body.error.message, "string");
	assert.ok(response.body.error.message.length > 0);
}

test("unknown routes and missing tasks use not_found envelopes", () => {
	for (const path of ["/unknown", "/tasks/missing/extra"]) {
		expectError(request("GET", path), 404, "not_found");
	}
	for (const method of ["GET", "PATCH"]) {
		expectError(request(method, "/tasks/missing", "{}"), 404, "not_found");
	}
});

test("unsupported methods use method_not_allowed envelopes", () => {
	for (const [method, path] of [["DELETE", "/tasks/id"], ["POST", "/tasks/id"], ["PATCH", "/tasks"]]) {
		expectError(request(method, path, "{}"), 405, "method_not_allowed");
	}
});

test("invalid limits are rejected rather than clamped", () => {
	for (const limit of ["0", "-1", "101", "1.5", "abc", "", "Infinity"]) {
		expectError(request("GET", `/tasks?limit=${limit}`), 400, "invalid_limit");
	}
	for (const path of ["/tasks", "/tasks?limit=1", "/tasks?limit=100"]) {
		assert.equal(request("GET", path).status, 200);
	}
});

test("invalid titles use invalid_title envelopes", () => {
	for (const title of [undefined, null, "", "  ", 42, {}, []]) {
		expectError(request("POST", "/tasks", JSON.stringify({ title })), 400, "invalid_title");
	}
});

test("malformed JSON and non-object bodies use error envelopes for both writes", () => {
	for (const [method, path] of [["POST", "/tasks"], ["PATCH", "/tasks/missing"]]) {
		expectError(request(method, path, "{"), 400, "invalid_json");
		for (const body of ["null", "[]", "42", '"text"']) {
			expectError(request(method, path, body), 400, "invalid_body");
		}
	}
});

test("successful task operations retain their response shapes", () => {
	const created = request("POST", "/tasks", JSON.stringify({ title: "route test" }));
	assert.equal(created.status, 201);
	const path = `/tasks/${created.body.id}`;
	assert.deepEqual(request("GET", path), { status: 200, body: created.body });
	const updated = request("PATCH", path, JSON.stringify({ status: "done" }));
	assert.equal(updated.status, 200);
	assert.equal(updated.body.status, "done");
	assert.ok(Array.isArray(request("GET", "/tasks").body.items));
});

