import assert from "node:assert/strict";
import { test } from "node:test";
import { handle } from "../src/routes/tasks.js";
import { createTask, updateTask } from "../src/store.js";

function list(query = "") {
	return handle("GET", new URL(`/tasks${query}`, "http://localhost"));
}

test("GET /tasks filters open and done tasks before applying the limit", () => {
	const open = createTask("open task");
	const done = createTask("done task");
	updateTask(done.id, { status: "done" });
	const openResponse = list("?status=open");
	assert.equal(openResponse.status, 200);
	assert.deepEqual(openResponse.body.items.map(task => task.id), [open.id]);
	const doneResponse = list("?status=done&limit=1");
	assert.equal(doneResponse.status, 200);
	assert.deepEqual(doneResponse.body.items.map(task => task.id), [done.id]);
	assert.equal(doneResponse.body.items[0].status, "done");
	assert.deepEqual(list().body.items.map(task => task.id), [open.id, done.id]);
});

test("GET /tasks rejects invalid status values with the error envelope", () => {
	for (const status of ["", "pending", "OPEN", "Done", "null", "open,done", " open "]) {
		const response = list(`?status=${encodeURIComponent(status)}`);
		assert.equal(response.status, 400);
		assert.deepEqual(response.body, {
			error: { code: "invalid_status", message: "status must be open or done" },
		});
	}
});

test("GET /tasks returns an empty list when no tasks match", () => {
	for (const task of list("?status=open&limit=50").body.items) {
		updateTask(task.id, { status: "done" });
	}
	assert.deepEqual(list("?status=open"), { status: 200, body: { items: [] } });
});

