test("DELETE hides a cached task from GET, listings, and PATCH", () => {
	const task = createTask("delete this task");
	const survivor = createTask("keep this task");
	const path = `/tasks/${task.id}`;
	assert.equal(request("GET", path).status, 200);
	assert.deepEqual(request("DELETE", path), { status: 204 });
	expectNotFound(request("GET", path));
	expectNotFound(request("PATCH", path, JSON.stringify({ status: "done" })));
	for (const query of ["", "?status=open", "?status=done"]) {
		const response = request("GET", `/tasks${query}`);
		assert.equal(response.status, 200);
		assert.ok(!response.body.items.some(item => item.id === task.id));
	}
	assert.equal(request("GET", `/tasks/${survivor.id}`).status, 200);
	expectNotFound(request("DELETE", path));
	expectNotFound(request("DELETE", "/tasks/unknown"));
});

test("deleted tasks do not consume page slots", () => {
	const deleted = createTask("deleted done task");
	updateTask(deleted.id, { status: "done" });
	const visible = createTask("visible done task");
	updateTask(visible.id, { status: "done" });
	request("DELETE", `/tasks/${deleted.id}`);
	const response = request("GET", "/tasks?status=done&limit=1");
	assert.deepEqual(response.body.items.map(task => task.id), [visible.id]);
});

