	assert.equal(getTask(task.id), undefined);
	assert.ok(!listTasks().some(item => item.id === task.id));
	assert.equal(updateTask(task.id, { title: "resurrect" }), undefined);
	assert.equal(deleteTask(task.id), false);
	assert.equal(deleteTask("unknown"), false);
	assert.equal(task.deleted_at, null);
});

