import { createTask, deleteTask, getTask, listTasks, updateTask } from "../store.js";

function error(status, code, message) {
	return { status, body: { error: { code, message } } };
}

function taskResponse(task) {
	return task
		? { status: 200, body: task }
		: error(404, "not_found", "not found");
}

function listResponse(url) {
	const limit = Number(url.searchParams.get("limit") ?? 25);
	if (!Number.isInteger(limit) || limit < 1 || limit > 50) {
		return error(400, "invalid_limit", "limit must be an integer between 1 and 50");
	}
	const status = url.searchParams.get("status");
	if (status !== null && status !== "open" && status !== "done") {
		return error(400, "invalid_status", "status must be open or done");
	}
	const items = listTasks().filter(task => status === null || task.status === status);
	return { status: 200, body: { items: items.slice(0, limit) } };
}

function writeResponse(method, id, body) {
	let data;
	try {
		data = JSON.parse(body || "{}");
	} catch {
		return error(400, "invalid_json", "request body must be valid JSON");
	}
	if (!data || typeof data !== "object" || Array.isArray(data)) {
		return error(400, "invalid_body", "request body must be a JSON object");
	}
	if (method === "PATCH") return taskResponse(updateTask(id, data));
	if (typeof data.title !== "string" || !data.title.trim()) {
		return error(400, "invalid_title", "title must be a non-empty string");
	}
	return { status: 201, body: createTask(data.title) };
}

export function handle(method, url, body) {
	const parts = url.pathname.split("/").filter(Boolean);
	if (parts[0] !== "tasks" || parts.length > 2) {
		return error(404, "not_found", "not found");
	}
	if (method === "GET" && parts.length === 1) return listResponse(url);
	if (method === "POST" && parts.length === 1) return writeResponse(method, undefined, body);
	if (method === "DELETE" && parts.length === 2) {
		return deleteTask(parts[1])
			? { status: 204 }
			: error(404, "not_found", "not found");
	}
	if (method === "GET") return taskResponse(getTask(parts[1]));
	if (method === "PATCH" && parts.length === 2) return writeResponse(method, parts[1], body);
	return error(405, "method_not_allowed", "method not allowed");
}

// In-memory task store.
import { ulid } from "./ulid.js";

const tasks = new Map();
const serializedTasks = new Map();
const CACHE_LIMIT = 500;

function cacheKey(task) {
	return JSON.stringify([task.id, task.updated_at]);
}

function timestamp(now) {
	return now.toISOString().replace(/\.\d{3}Z$/, "Z");
}

export function createTask(title, now = new Date()) {
	const id = ulid();
	const stamp = timestamp(now);
	const task = { id, title, status: "open", created_at: stamp, updated_at: stamp, deleted_at: null };
	tasks.set(id, task);
	return serializeTask(task);
}

export function updateTask(id, changes, now = new Date()) {
	const task = tasks.get(id);
	if (!task || task.deleted_at) return undefined;
	serializedTasks.delete(cacheKey(task));
	Object.assign(task, changes, { updated_at: timestamp(now) });
	return serializeTask(task);
}

export function deleteTask(id, now = new Date()) {
	const task = tasks.get(id);
	if (!task || task.deleted_at) return false;
	serializedTasks.delete(cacheKey(task));
	const stamp = timestamp(now);
	Object.assign(task, { deleted_at: stamp, updated_at: stamp });
	return true;
}

export function listTasks() {
	return [...tasks.values()].filter(task => !task.deleted_at).map(serializeTask);
}

export function getTask(id) {
	const task = tasks.get(id);
	return task && !task.deleted_at ? serializeTask(task) : undefined;
}

export function serializeTask(task) {
	const key = cacheKey(task);
	const serialized = serializedTasks.get(key) ?? Object.freeze({ ...task });
	serializedTasks.delete(key);
	serializedTasks.set(key, serialized);
	if (serializedTasks.size > CACHE_LIMIT) {
		serializedTasks.delete(serializedTasks.keys().next().value);
	}
	return serialized;
}

